{
  "solutions": [
    {
      "id": "P5",
      "verified": true,
      "selfContained": true,
      "sourceSupported": true,
      "hardReasoning": true,
      "question": "Lập luận cho rằng chỉ chạy chế độ B với số chu trình đủ để đạt tải nhiệt $2160\\,\\mathrm{kJ}$ luôn thỏa thời gian tối đa $200\\,\\mathrm{s}$ và ngân sách điện $800\\,\\mathrm{kJ}$ là sai. Lý do nào sau đây chứng minh sai lầm này?",
      "solution": "Cần ít nhất $\\frac{2160}{600}=3.6$ chu trình B, tức ít nhất 4 chu trình. Thời gian tiêu thụ $4\\times40\\,\\mathrm{s}=160\\,\\mathrm{s}\\le200\\,\\mathrm{s}$, nhưng năng lượng tiêu thụ $4\\times240\\,\\mathrm{kJ}=960\\,\\mathrm{kJ}>800\\,\\mathrm{kJ}$, vượt ngân sách điện. Do đó lập luận sai vì không xét đến ràng buộc năng lượng.",
      "claims": [
        {
          "text": "Với 4 chu trình B, thời gian tiêu thụ là $4\\times40\\,\\mathrm{s}=160\\,\\mathrm{s}\\le200\\,\\mathrm{s}$ nhưng năng lượng tiêu thụ là $4\\times240\\,\\mathrm{kJ}=960\\,\\mathrm{kJ}>800\\,\\mathrm{kJ}$, vì vậy ngân sách điện bị vượt.",
          "correct": true,
          "misconception": null
        },
        {
          "text": "Với 4 chu trình B, cả thời gian $160\\,\\mathrm{s}$ và năng lượng $960\\,\\mathrm{kJ}$ đều nằm trong giới hạn cho phép.",
          "correct": false,
          "misconception": "không nhận xét về vượt quá năng lượng"
        },
        {
          "text": "Với 3 chu trình B, thời gian và năng lượng đều đáp ứng, nhưng nhiệt thu được chỉ $3\\times600\\,\\mathrm{kJ}=1800\\,\\mathrm{kJ}<2160\\,\\mathrm{kJ}$, không đạt yêu cầu.",
          "correct": false,
          "misconception": "không đạt yêu cầu nhiệt"
        },
        {
          "text": "Với 5 chu trình B, thời gian tiêu thụ là $5\\times40\\,\\mathrm{s}=200\\,\\mathrm{s}$ vừa đủ, còn năng lượng $5\\times240\\,\\mathrm{kJ}=1200\\,\\mathrm{kJ}$ vẫn dưới $800\\,\\mathrm{kJ}$.",
          "correct": false,
          "misconception": "sai tính năng lượng"
        }
      ]
    },
    {
      "id": "P7",
      "verified": true,
      "selfContained": true,
      "sourceSupported": true,
      "hardReasoning": true,
      "question": "Khi cố gắng đạt nhiệt tối đa có thể, tính lượng nhiệt lớn nhất có thể thu được nếu chỉ bị giới hạn bởi thời gian $200\\,\\mathrm{s}$ và nếu chỉ bị giới hạn bởi ngân sách điện $800\\,\\mathrm{kJ}$. Ràng buộc nào là giới hạn quyết định?",
      "solution": "Hiệu suất nhiệt trên mỗi giây: chế độ A $540\\,\\mathrm{kJ}/60\\,\\mathrm{s}=9\\,\\mathrm{kJ\\,s^{-1}}$, chế độ B $600\\,\\mathrm{kJ}/40\\,\\mathrm{s}=15\\,\\mathrm{kJ\\,s^{-1}}$. Để tối đa thời gian, dùng toàn bộ chế độ B: $200\\,\\mathrm{s}/40\\,\\mathrm{s}=5$ chu trình, nhiệt $5\\times600=3000\\,\\mathrm{kJ}$. Để tối đa năng lượng, dùng chế độ A: $800\\,\\mathrm{kJ}/180\\,\\mathrm{kJ}=4.44$ chu trình, nhiệt $4.44\\times540=2400\\,\\mathrm{kJ}$. Vì $2400\\,\\mathrm{kJ}<3000\\,\\mathrm{kJ}$, ràng buộc năng lượng là giới hạn quyết định.",
      "answer": "Ràng buộc năng lượng",
      "claims": []
    },
    {
      "id": "P8",
      "verified": true,
      "selfContained": true,
      "sourceSupported": true,
      "hardReasoning": true,
      "question": "Giả sử hiện tại một tổ hợp các chu trình đáp ứng cả thời gian $200\\,\\mathrm{s}$ và ngân sách điện $800\\,\\mathrm{kJ}$ vừa đủ để đạt tải $2160\\,\\mathrm{kJ}$. Nếu tăng thêm một chu trình của chế độ B, ràng buộc nào sẽ bị vi phạm đầu tiên?",
      "solution": "Trong cấu hình hiện tại thời gian và năng lượng đều đã đạt mức tối đa (ví dụ $n_A\\approx2.22$, $n_B\\approx1.67$). Thêm một chu trình B làm tăng thời gian $+40\\,\\mathrm{s}$ và năng lượng $+240\\,\\mathrm{kJ}$, vì không còn dư thời gian hay năng lượng nào, cả hai ràng buộc đều bị vượt cùng lúc. Do đó không có ràng buộc nào “đầu tiên” riêng; cả thời gian và ngân sách điện đều vi phạm đồng thời.",
      "claims": [
        {
          "text": "Việc tăng thêm một chu trình B sẽ đồng thời làm thời gian vượt quá $200\\,\\mathrm{s}$ và năng lượng vượt quá $800\\,\\mathrm{kJ}$, vì cả hai ràng buộc đã đạt mức tối đa trong cấu hình hiện tại.",
          "correct": true,
          "misconception": null
        },
        {
          "text": "Chỉ thời gian sẽ bị vượt quá, trong khi ngân sách điện vẫn còn dư.",
          "correct": false,
          "misconception": "bỏ qua giới hạn năng lượng"
        },
        {
          "text": "Chỉ ngân sách điện sẽ bị vượt quá, thời gian vẫn còn chỗ.",
          "correct": false,
          "misconception": "bỏ qua giới hạn thời gian"
        },
        {
          "text": "Không vi phạm bất kỳ ràng buộc nào vì còn dư thời gian và năng lượng.",
          "correct": false,
          "misconception": "không nhận xét về ràng buộc hiện tại"
        }
      ]
    },
    {
      "id": "P6",
      "verified": true,
      "selfContained": true,
      "sourceSupported": true,
      "hardReasoning": true,
      "question": "Xác định liệu có thể đáp ứng yêu cầu lấy nhiệt tổng cộng $2160\\,\\mathrm{kJ}$ trong thời gian không vượt quá $200\\,\\mathrm{s}$ và ngân sách điện không vượt quá $800\\,\\mathrm{kJ}$, và nếu có, xác định số chu trình (có thể là phân số) của chế độ A và B cần chạy. Chọn tất cả các phát biểu đúng.",
      "solution": "Ta xét các bất phương trình:\n\\[60 n_A + 40 n_B \\le 200,\\]\n\\[180 n_A + 240 n_B \\le 800,\\]\n\\[540 n_A + 600 n_B \\ge 2160.\\]\nGiải hệ thời gian và năng lượng đồng thời cho $n_A$ và $n_B$ cho ta $n_A\\approx2.22$, $n_B\\approx1.67$, thỏa cả ba ràng buộc (nhiệt thu được $\\approx2200\\,\\mathrm{kJ}>2160\\,\\mathrm{kJ}$). Vì tồn tại nghiệm khả thi, yêu cầu có thể đáp ứng. Các phát biểu sau được suy ra:\n- Có thể đáp ứng yêu cầu mà không vượt quá thời gian và ngân sách.\n- Một tổ hợp khả thi là $n_A\\approx2.22$ chu trình A và $n_B\\approx1.67$ chu trình B.\n- Nếu chỉ dùng chế độ B, cần 4 chu trình để đạt $2160\\,\\mathrm{kJ}$ nhưng năng lượng tiêu thụ $960\\,\\mathrm{kJ}>800\\,\\mathrm{kJ}$, vi phạm ngân sách.\n- Nếu chỉ dùng chế độ A, cần 4 chu trình để đạt $2160\\,\\mathrm{kJ}$ nhưng thời gian $4\\times60=240\\,\\mathrm{s}>200\\,\\mathrm{s}$, vi phạm thời gian.\nDo đó các phát biểu 1, 2 và 3 là đúng, phát biểu 4 là sai.",
      "claims": [
        {
          "text": "Có thể đáp ứng yêu cầu $2160\\,\\mathrm{kJ}$ mà vẫn không vượt quá thời gian $200\\,\\mathrm{s}$ và ngân sách điện $800\\,\\mathrm{kJ}$.",
          "correct": true,
          "misconception": null
        },
        {
          "text": "Một tổ hợp khả thi là khoảng $n_A=2.22$ chu trình chế độ A và $n_B=1.67$ chu trình chế độ B, đáp ứng cả ba ràng buộc.",
          "correct": true,
          "misconception": null
        },
        {
          "text": "Nếu chỉ dùng chế độ B, cần $4$ chu trình để đạt $2160\\,\\mathrm{kJ}$ nhưng sẽ vượt quá ngân sách điện $800\\,\\mathrm{kJ}$.",
          "correct": true,
          "misconception": null
        },
        {
          "text": "Nếu chỉ dùng chế độ A, cần $3$ chu trình để đạt $2160\\,\\mathrm{kJ}$ và thời gian sẽ vẫn dưới $200\\,\\mathrm{s}$.",
          "correct": false,
          "misconception": "không đáp ứng yêu cầu nhiệt"
        }
      ]
    }
  ]
}
